<script setup>
import { computed, ref, watch } from 'vue'
import AssessmentStationIcon from './AssessmentStationIcon.vue'
import { useAxiosAuth } from '@/composables/axios-auth'
import { resultSummary } from '@/pages/free-assessment/workflow'
import { categoryTiles, stationOrder, ordinal, historicalComparison } from './reportPresentation'
const props = defineProps({ assessmentId: { type: String, required: true }, playerId: { type: String, required: true } })
const { axiosGet } = useAxiosAuth()
const report = ref(null), error = ref(''), loading = ref(false), activeTab = ref('Overview'), shareNotice = ref(''), photoFailed = ref(false)
const tabs = ['Overview', 'Results', 'Rankings', 'Strengths & Development', 'Historical Comparison']
let generation = 0
async function load() {
  const current = ++generation
  report.value = null; error.value = ''; loading.value = true; shareNotice.value = ''; photoFailed.value = false
  try {
    const { data } = await axiosGet(`free-assessment-reports/${props.assessmentId}/players/${props.playerId}`)
    if (current === generation) report.value = data.data
  } catch (e) { if (current === generation) error.value = e?.response?.data?.message || 'Could not load this assessment report.' }
  finally { if (current === generation) loading.value = false }
}
watch(() => [props.assessmentId, props.playerId], load, { immediate: true })
const result = key => report.value?.results.find(r => r.station === key)
const tiles = computed(() => report.value ? categoryTiles(report.value) : [])
const summary = r => resultSummary(r, report.value.stations)
const comparisons = computed(() => (report.value?.results || []).filter(r => r.peer_percentile !== null && r.peer_percentile !== undefined))
const strengths = computed(() => [...comparisons.value].filter(r => r.peer_percentile >= 75).sort((a,b) => b.peer_percentile-a.peer_percentile).slice(0,3))
const opportunities = computed(() => [...comparisons.value].filter(r => r.peer_percentile < 50).sort((a,b) => a.peer_percentile-b.peer_percentile).slice(0,3))
const notes = computed(() => (report.value?.results || []).filter(r => r.notes))
const average = r => !r ? '—' : r.station === 'grip_strength' ? `L ${r.summary.left.average ?? '—'} / R ${r.summary.right.average ?? '—'}` : r.summary.average
const date = value => new Date(`${value}T12:00:00`).toLocaleDateString()
const initials = computed(() => report.value?.player.name.split(' ').filter(Boolean).slice(0,2).map(v => v[0]).join(''))
const history = key => historicalComparison(report.value, key)
const printReport = () => window.print()
async function copyReportLink() {
  const url = new URL('/assessment-reports', window.location.origin)
  url.search = new URLSearchParams({ kind: 'free_assessment', assessment: props.assessmentId, player: props.playerId }).toString()
  try { await navigator.clipboard.writeText(url.href); shareNotice.value = 'Report link copied. The recipient must sign in and have access to this player.' }
  catch (_) { shareNotice.value = `Copy this report link (sign-in required): ${url.href}` }
}
</script>
<template>
  <section class="free-player-report">
    <p v-if="loading" role="status">Loading Free Assessment report…</p>
    <div v-else-if="error" role="alert">{{ error }} <button @click="load">Retry</button></div>
    <article v-else-if="report" class="free-report-print">
      <div class="report-toolbar no-print"><span>Players <span aria-hidden="true">›</span> {{ report.player.name }} <span aria-hidden="true">›</span> <b>Assessment Report</b></span><div><button @click="copyReportLink">↗ Share Report</button><button class="primary" @click="printReport">↓ Print / Save PDF</button></div></div>
      <p v-if="shareNotice" role="status" class="share-notice no-print">{{ shareNotice }}</p>
      <div class="print-brand">FMTRX <span>TRAIN. TRACK. IMPROVE. · PLAYER ASSESSMENT REPORT</span></div>
      <header class="athlete-header">
        <div class="portrait"><img v-if="report.player.picture && !photoFailed" :src="report.player.picture" :alt="report.player.name" @error="photoFailed = true"><span v-else>{{ initials }}</span></div>
        <div class="athlete-info"><h1>{{ report.player.name }}</h1><p>Age: {{ report.player.age ?? '—' }} <i>│</i> Grad Year: {{ report.player.grad_year ?? '—' }} <i>│</i> {{ report.player.height || 'Height —' }} <i>│</i> {{ report.player.weight ?? '—' }} lbs</p><p>Position: {{ report.player.position || '—' }} <i>│</i> Bats/Throws: {{ report.player.bats || '—' }}/{{ report.player.throws || '—' }} <i>│</i> {{ report.assessment.name }}</p><p class="event-line">▦ Assessment Date: {{ date(report.assessment.assessment_date) }} <span>⌖ {{ report.assessment.location }}</span></p><small>{{ report.completed_stations }}/{{ report.total_stations }} stations recorded · {{ report.assessment.status === 'completed' ? 'Completed' : 'In progress' }}</small></div>
        <aside class="overall-card"><h2>Overall Athlete Score</h2><strong>{{ report.overall_score ?? '—' }}<small v-if="report.overall_score !== null"> / 100</small></strong><p>{{ report.overall_score_note }}</p></aside>
      </header>
      <nav class="report-tabs no-print" aria-label="Report sections"><button v-for="tab in tabs" :key="tab" :class="{ active: activeTab === tab }" :aria-pressed="activeTab === tab" @click="activeTab = tab">{{ tab }}</button></nav>
      <div class="category-grid print-section" v-show="activeTab === 'Overview'"><article v-for="tile in tiles" :key="tile.name"><span class="category-icon"><AssessmentStationIcon :station="tile.keys[0]" /></span><h2>{{ tile.name }}</h2><strong>{{ ordinal(tile.percentile) }}</strong><p>Age/peer percentile</p><small>{{ tile.result ? report.stations[tile.result.station].name + (tile.result.station === 'grip_strength' ? ' (L)' : '') : 'Not tested' }}</small><div class="meter"><span :style="{ width: `${tile.percentile ?? 0}%` }"></span></div></article></div>
      <div class="report-grid" :class="{ 'single-column': !['Overview','Strengths & Development'].includes(activeTab), 'focus-view': activeTab === 'Strengths & Development' }">
        <div class="main-column">
          <section class="report-panel details-panel print-section" v-show="['Overview','Results','Rankings'].includes(activeTab)"><h2>{{ activeTab === 'Rankings' ? 'Assessment Rankings' : 'Detailed Results' }}</h2><div class="table-scroll"><table><thead><tr><th>Station / Metric</th><th>Result</th><th>Assessment Rank</th><th>Age/Peer Percentile</th><th>Yard/FMTRX Percentile</th></tr></thead><tbody><tr v-for="key in stationOrder" :key="key"><th>{{ report.stations[key].name }} <small>({{ result(key)?.values.filter(v => v !== null).length ?? 0 }} recorded / {{ report.stations[key].count }} possible)</small></th><template v-if="result(key)"><td><b>{{ summary(result(key)) }}</b><small v-if="report.stations[key].count > 1">Avg: {{ average(result(key)) }} {{ report.stations[key].unit }}</small><small v-if="result(key).protocol">{{ result(key).protocol }}</small><details v-if="activeTab === 'Results'" class="no-print"><summary>Raw attempts</summary>{{ result(key).values.map(v => v ?? '—').join(' · ') }} {{ report.stations[key].unit }}<p v-if="key === 'grip_strength'">First 3 left; last 3 right.</p></details></td><td>{{ result(key).rank == null ? '—' : '#' + result(key).rank }} <small>of {{ result(key).participants }}</small></td><td>{{ ordinal(result(key).peer_percentile) }}<small v-if="result(key).peer_percentile !== null">{{ result(key).peer_confidence }} confidence</small></td><td>{{ ordinal(result(key).population_percentile) }}<small>{{ result(key).confidence }} confidence</small></td></template><td v-else colspan="4" class="not-tested">Not tested</td></tr></tbody></table></div><p class="caption">Ranks compare matching station protocols; grip rank uses the left hand. A dash means the benchmark is unavailable or has insufficient data.</p></section>
          <section class="report-panel chart-panel print-section" v-show="['Overview','Rankings'].includes(activeTab)"><h2>Percentile Breakdown</h2><div class="chart-legend"><span><i class="peer-key"></i>Age/peer percentile</span><span><i class="yard-key"></i>Yard/FMTRX percentile</span></div><div class="chart-scroll"><div class="chart"><div class="axis"><span>100</span><span>75</span><span>50</span><span>25</span><span>0</span></div><div class="plot"><div v-for="key in stationOrder" :key="key" class="bar-group"><div class="bars"><span class="peer-bar" :style="{ height: `${result(key)?.peer_percentile ?? 0}%` }" :aria-label="`${report.stations[key].name} age/peer: ${ordinal(result(key)?.peer_percentile)}`"></span><span class="yard-bar" :style="{ height: `${result(key)?.population_percentile ?? 0}%` }" :aria-label="`${report.stations[key].name} Yard/FMTRX: ${ordinal(result(key)?.population_percentile)}`"></span></div><small>{{ report.stations[key].name }}</small></div></div></div></div><p class="caption">Bars show the available percentiles above. Missing benchmarks have no bar. Category cards show a recorded test, not a combined category score.</p></section>
          <section v-if="activeTab === 'Historical Comparison'" class="report-panel no-print"><h2>Historical Comparison</h2><p class="caption">Compared with the most recent earlier compatible test for this player on the same team.</p><div class="table-scroll"><table><thead><tr><th>Station</th><th>Previous</th><th>Current</th><th>Change</th></tr></thead><tbody><tr v-for="key in stationOrder" :key="key"><th>{{ report.stations[key].name }}</th><template v-if="history(key)"><td>{{ history(key).previous }} {{ report.stations[key].unit }}<small>{{ date(history(key).date) }}</small></td><td>{{ history(key).current }} {{ report.stations[key].unit }}</td><td :class="{ improved: history(key).improved, declined: history(key).improved === false }">{{ history(key).change > 0 ? '+' : '' }}{{ history(key).change }} {{ report.stations[key].unit }}<small>{{ history(key).improved === null ? 'Unchanged' : history(key).improved ? 'Improved' : 'Decreased performance' }}</small></td></template><td v-else colspan="3">No earlier compatible result</td></tr></tbody></table></div></section>
        </div>
        <aside class="insight-column print-section" v-show="['Overview','Strengths & Development'].includes(activeTab)">
          <section class="report-panel strengths"><h2><span>↑</span> Top Strengths</h2><ol><li v-for="(r,i) in strengths" :key="r.station"><span class="rank-dot">{{ i+1 }}</span><div><b>{{ report.stations[r.station].name }}</b><p>{{ ordinal(r.peer_percentile) }} percentile</p><small>{{ r.peer_confidence }} confidence</small></div></li></ol><p v-if="!strengths.length" class="caption">No recorded test with an available benchmark meets the 75th-percentile threshold yet.</p></section>
          <section class="report-panel opportunities"><h2><span>↓</span> Development Opportunities</h2><ol><li v-for="(r,i) in opportunities" :key="r.station"><span class="rank-dot">{{ i+1 }}</span><div><b>{{ report.stations[r.station].name }}</b><p>{{ ordinal(r.peer_percentile) }} percentile</p><small>{{ r.peer_confidence }} confidence</small></div></li></ol><p v-if="!opportunities.length" class="caption">No recorded test with an available benchmark falls below the 50th percentile.</p></section>
          <section class="report-panel next-steps"><h2>▣ Next Steps</h2><ul><li>Review these results with your coach.</li><li v-if="opportunities.length">Discuss a training focus for {{ opportunities.map(r => report.stations[r.station].name).join(', ') }}.</li><li v-if="report.completed_stations < report.total_stations">Complete the remaining assessment stations.</li><li>Use the same test protocols when you retest to track progress.</li></ul><p class="caption">Your coach can use these results to plan your next training block.</p></section>
          <section class="report-panel assessment-notes"><h2>▤ Assessment Notes</h2><div v-for="r in notes" :key="r.station" class="note"><b>{{ report.stations[r.station].name }}</b><p>{{ r.notes }}</p><small>— {{ r.coach }}</small></div><p v-if="!notes.length" class="caption">No coach notes recorded.</p></section>
        </aside>
      </div>
      <footer><b>FMTRX</b> Train. Track. Improve. <span>Assessment results are based on recorded tests. Percentiles include the confidence shown; unavailable metrics are not scored.</span></footer>
    </article>
  </section>
</template>
<style scoped>
