ff}.category-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-bottom:16px}.category-grid article{text-align:center;border:1px solid #e1e8f1;border-radius:8px;padding:14px 8px;background:linear-gradient(180deg,#fff,#f7faff)}.category-icon{color:#10213a;display:block;height:32px;width:32px;margin:0 auto}.category-grid h2{text-transform:uppercase;font-size:11px;margin:6px 0}.category-grid strong{font-size:25px;font-weight:850}.category-grid p{font-size:10px}.category-grid small{display:block;min-height:24px;font-size:9px;color:#536b83}.meter{height:7px;background:#dce5ef;border-radius:8px;overflow:hidden;margin-top:10px}.meter span{display:block;height:100%;background:#0866ff;border-radius:8px}.report-grid{display:grid;grid-template-columns:minmax(0,1.85fr) minmax(240px,1fr);gap:14px;align-items:start}.main-column,.insight-column{display:grid;gap:14px;min-width:0}.single-column,.focus-view{grid-template-columns:1fr}.focus-view .main-column{display:none}.focus-view .insight-column{display:grid;grid-template-columns:1fr 1fr}.report-panel{border:1px solid #e0e7ef;border-radius:9px;padding:15px;background:#fff}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:10px}thead{background:#f1f5fa}th,td{padding:12px 7px;text-align:left;border-bottom:1px solid #e5ebf2;vertical-align:middle}thead th{font-size:10px;font-weight:750}tbody th{font-size:10px;font-weight:700;width:28%}td small,th small{display:block;font-size:9px;font-weight:400;color:#506782;margin-top:3px}td b{font-size:10px;font-weight:600}.not-tested{color:#8593a6}.caption{font-size:10px!important;color:#60748c!important;margin-top:10px!important}.chart-legend{display:flex;flex-wrap:wrap;gap:20px;font-size:10px;color:#526783;margin:10px 0 18px}.chart-legend i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.peer-key,.peer-bar{background:#0768ff}.yard-key,.yard-bar{background:#a9c4e6}.chart-scroll{overflow-x:auto}.chart{display:fle