</style>
<style>
@media print {
  body:has(.free-report-print){page:free-assessment-page}
  @page free-assessment-page {size:A4 portrait;margin:10mm}
  html:has(.free-report-print),body:has(.free-report-print),body:has(.free-report-print) #app{height:auto!important;overflow:visible!important;background:#fff!important}
  body:has(.free-report-print) *{visibility:hidden}
  body:has(.free-report-print) .free-report-print,body:has(.free-report-print) .free-report-print *{visibility:visible}
  body:has(.free-report-print) .free-report-print{position:absolute;left:0;top:0;width:100%;box-sizing:border-box}
  body:has(.free-report-print) .assessment-page{height:auto!important;overflow:visible!important}
}
